(() => {
'use strict';
const app=document.querySelector('#app'),dialog=document.querySelector('#modal'),modal=document.querySelector('#modal-content');
const KEY='pendingcrew-product-tour-v1',labels={open:'待开始',active:'进行中',blocked:'等待答复',done:'已完成',dropped:'已结束'},scopeNames={message:'消息',todo:'Todo',document:'文档',progress:'进展'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={search:'<circle cx="7" cy="7" r="4.8"/><path d="m10.7 10.7 3.5 3.5"/>',plus:'<path d="M8 2v12M2 8h12"/>',refresh:'<path d="M13 5a5.5 5.5 0 1 0 0 6M13 1v4H9"/>',panel:'<rect x="1.5" y="2" width="13" height="12" rx="2"/><path d="M10 2v12"/>',folder:'<path d="M1.5 4V13h13V5H8L6 3H2z"/>',file:'<path d="M3 1.5h7l3 3V14H3zM10 2v3h3M5 8h6M5 11h6"/>',menu:'<path d="M2 4h12M2 8h12M2 12h12"/>',arrow:'<path d="m9 3-5 5 5 5"/>',info:'<circle cx="8" cy="8" r="6.5"/><path d="M8 7v5M8 4v.5"/>',more:'<circle cx="3" cy="8" r=".5"/><circle cx="8" cy="8" r=".5"/><circle cx="13" cy="8" r=".5"/>'};return `<svg class="icon" viewBox="0 0 16 16" aria-hidden="true">${paths[name]||paths.info}</svg>`;};
const btn=(action,text,extra='',cls='text-button')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const glyphs=['🦊','🐼','🐯','🦁','🐸','🐧','🐳','🐙','🦉','🦄','🐝','🦋','🐢','🐬','🦒','🦔','🌵','🌻','🌸','🌙','⭐','🔥','🍄','🍀','🍓','🍑','🍋','🍇','🥑','🌽','🥨','🍪','🎈','🎨','🎭','🎪','🎲','🧩','🪁','🪐','🚀','⛵','🏕','🪴','🪨','💎','🧊','🦤'];
function avatar(seed,group=false,glyph='🦉') {if(!group)return `<span class="avatar single" aria-hidden="true">${glyph}</span>`;let h=1469598103934665603n;for(const c of seed)h=BigInt.asUintN(64,(h^BigInt(c.codePointAt(0)))*1099511628211n);const picked=[];while(picked.length<3){const g=glyphs[Number(h%48n)];if(!picked.includes(g))picked.push(g);h=BigInt.asUintN(64,h*6364136223846793005n+1442695040888963407n);}return `<span class="avatar group" aria-hidden="true">${picked.map((g,i)=>`<span style="--dx:${[0,-5.3,5.3][i]}px;--dy:${[-6.1,3.1,3.1][i]}px">${g}</span>`).join('')}</span>`;}
function fresh(id){const scene=DEMO_SCENARIOS.find(s=>s.id===id),data=makeDemo(scene);for(const [conv,msgs] of Object.entries(data.messages))msgs.forEach((m,i)=>{m.id=conv+'-'+i;m.folder=m.ref?.startsWith('H')?scene.folderNames.message[1]:scene.folderNames.message[0];});return {db:data,tab:'message',kind:'requests',conv:id+'-main',sidebar:'hierarchy',collapsed:[],selectedFolders:{message:'all',todo:'all',document:'all',progress:'all'},inspector:innerWidth>=1000,todoClosed:false,membersClosed:false,drafts:{},doc:null,mentions:false,query:'',mobileChat:false,machineClosed:false,mode:'human',askScope:'crew',counter:0};}
let sceneId='website',cache={},state,toastTimer,simulationTimer;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.extraScenarios))DEMO_SCENARIOS.push(...saved.extraScenarios.filter(s=>s.id?.startsWith('custom-')&&s.folderNames));if(saved?.version===1&&DEMO_SCENARIOS.some(s=>s.id===saved.sceneId)){sceneId=saved.sceneId;cache=saved.cache||{};}}catch{}
const scene=()=>DEMO_SCENARIOS.find(s=>s.id===sceneId),db=()=>state.db;
function persist(){cache[sceneId]=state;try{localStorage.setItem(KEY,JSON.stringify({version:1,sceneId,cache,extraScenarios:DEMO_SCENARIOS.filter(s=>s.id.startsWith('custom-'))}));}catch{}}
function selectScene(id){clearTimeout(simulationTimer);if(state)persist();sceneId=id;state=cache[id]?.db?.plans?cache[id]:fresh(id);state.query='';state.mobileChat=false;app.classList.remove('show-sidebar');document.querySelector('#scenario').value=id;render();persist();scrollBottom();}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,3500);}
function statusBadge(status){return `<span class="badge ${esc(status)}">${labels[status]||esc(status)}</span>`;}
function refLabel(id){const p=db().plans.find(p=>p.id===id),a=db().asks.find(a=>a.id===id),d=db().docs.find(d=>d.id===id),r=db().requests.find(r=>r.id===id);return p?`${p.code} · ${p.title}`:a?`${a.id} · ${a.question}`:d?d.title:r?`${r.code} 原始需求`:id;}
function ref(id,cls='link-pill'){return btn('reference',esc(refLabel(id)),`data-id="${esc(id)}"`,cls);}
function folderOf(item,scope){if(scope==='todo'&&item.id?.startsWith('W'))return db().placements['todo:'+item.id]??db().requests.find(r=>item.sources?.includes(r.id))?.folder??'未分组';return db().placements[`${scope}:${item.id}`]??item.folder??'未分组';}
function filtered(items,scope){const f=state.selectedFolders[scope];return items.filter(x=>(f==='all'||folderOf(x,scope)===f)&&(!state.query||JSON.stringify(x).toLowerCase().includes(state.query.toLowerCase())));}
function folderSelect(scope,current){return `<select aria-label="${scopeNames[scope]}文件夹" data-folder-scope="${scope}"><option value="all" ${current==='all'?'selected':''}>全部${scopeNames[scope]}</option>${[...db().folders[scope],'未分组'].map(f=>`<option ${current===f?'selected':''}>${esc(f)}</option>`).join('')}</select>`;}
function crewColor(id){let h=1469598103934665603n;for(const c of id)h=BigInt.asUintN(64,(h^BigInt(c.codePointAt(0)))*1099511628211n);const hue=Number(h%360n),v=.82,sat=.62,c=v*sat,x=c*(1-Math.abs((hue/60)%2-1)),m=v-c;const rgb=hue<60?[c,x,0]:hue<120?[x,c,0]:hue<180?[0,c,x]:hue<240?[0,x,c]:hue<300?[x,0,c]:[c,0,x];return '#'+rgb.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('');}
function crewChain(id){const parents={website:'crew-product',trip:'crew-product',research:'trip'};const chain=[id],seen=new Set(chain);let parent=parents[id]||(id.startsWith('custom-')?'crew-product':null);while(parent&&!seen.has(parent)&&chain.length<8){chain.push(parent);seen.add(parent);parent=parents[parent];}return chain;}
function lineage(id){const chain=crewChain(id);let left=100,start=0;const stops=chain.map((c,i)=>{const size=i===chain.length-1?left:left/2,stop=crewColor(c)+' '+start+'% '+(start+size)+'%';left-=size;start+=size;return stop;});return `<span class="lineage" data-crew-color="${id}" style="background:linear-gradient(to bottom,${stops.join(',')})"></span>`;}
function sidebar(){const scenes=DEMO_SCENARIOS;const crew=(s,indent=0,alias=false)=>`<button class="crew-row ${s.id===sceneId?'selected':''}" style="padding-left:${indent+8}px" data-action="scene" data-id="${s.id}"><span class="chevron">${s.id==='trip'?'▾':''}</span>${lineage(s.id)}<span class="crew-text"><span class="crew-top"><span>${esc(s.crew)}${alias?' ↗':''}</span><small>${s.id===sceneId?'刚刚':'已整理'}</small></span><span class="crew-sub">${alias?'同一机组 · 另一父引用':esc(s.note)}</span></span></button>`;
return `<aside class="sidebar"><div class="side-toolbar"><div class="lights" aria-label="Mac 窗口装饰"><i></i><i></i><i></i></div><div class="tools">${btn('search',icon('search'),'aria-label="搜索介绍内容" title="搜索介绍内容"','icon-button')}${btn('new-crew',icon('plus'),'aria-label="新建机组" title="新建机组"','icon-button')}${btn('refresh',icon('refresh'),'aria-label="刷新" title="刷新"','icon-button')}</div></div><div class="segmented side-mode">${btn('sidebar','通讯录',`data-mode="hierarchy"`,' '+(state.sidebar==='hierarchy'?'active':''))}${btn('sidebar','消息',`data-mode="timeline"`,' '+(state.sidebar==='timeline'?'active':''))}</div><div class="side-list">${state.sidebar==='hierarchy'?`${btn('machine',(state.machineClosed?'▸':'▾')+' 本机','','machine')}${state.machineClosed?'':`<div class="crew-row"><span class="chevron">▾</span>${lineage('crew-product')}<span class="crew-text"><span class="crew-top">PendingCrew</span><span class="crew-sub">为持续任务流设计的人机协作工具</span></span></div>${scenes.map(s=>crew(s,s.id==='research'?30:15)).join('')}<div class="crew-row"><span class="chevron">▾</span>${lineage('crew-reading')}<span class="crew-text"><span class="crew-top">阅读入口</span><span class="crew-sub">按入口找到同一份介绍</span></span></div>${crew(scenes[2],15,true)}`}`:scenes.slice().sort((a,b)=>a.id===sceneId?-1:b.id===sceneId?1:0).map(s=>crew(s)).join('')}</div><div class="side-footer">${btn('hidden','已隐藏的群 ▸','','')}<div class="quota"><span class="quota-ring"></span>Codex · 额度</div><span>本机 · 产品介绍</span></div><div class="resize-x" data-resize="sidebar" aria-hidden="true"></div></aside>`;}
function shell(){return `${sidebar()}<button class="sidebar-scrim" data-action="close-sidebar" aria-label="收起机组列表"></button><section class="detail"><div class="titlebar">${btn('mobile-menu',icon('menu'),'aria-label="显示机组列表"','icon-button mobile-menu')}<h2>${esc(scene().crew)}</h2><span class="path">${esc(scene().root)} / 本机</span><span class="app-notice">交互介绍</span><label class="search">${icon('search')}<input aria-label="搜索当前机组" placeholder="搜索当前机组" value="${esc(state.query)}" id="search-input"></label><div class="tools">${btn('guide',icon('info'),'aria-label="了解这份介绍"','icon-button')}${btn('folder-manager',icon('more'),'aria-label="管理分组"','icon-button')}</div></div><nav class="view-tabs" aria-label="机组内容">${Object.entries(scopeNames).map(([k,v])=>btn('tab',v,`data-tab="${k}" aria-pressed="${state.tab===k}"`,state.tab===k?'active':'')).join('')}</nav><section class="view ${state.mobileChat?'mobile-chat':''}" id="main-view">${state.tab==='message'?chat():workspace()}</section></section>`;}
function chat(){const conv=db().conversations.find(c=>c.id===state.conv)||db().conversations[0],msgs=db().messages[conv.id]||[],filter=state.selectedFolders.message;
return `<aside class="conversation-list"><div class="list-filter">${folderSelect('message',filter)}${btn('folder-manager',icon('more'),'aria-label="管理消息文件夹"','icon-button')}</div><div class="conv-scroll">${db().conversations.map(c=>`<button class="conv-row ${c.id===conv.id?'selected':''}" data-action="conversation" data-id="${c.id}">${avatar(c.id,c.kind==='group',scene().glyph)}<span class="conv-content"><span class="conv-name"><span class="conv-title">${esc(c.title)}</span><small>${c.id===state.conv?'13:20':'13:10'}</small></span><span class="conv-sub">${esc((db().messages[c.id]||[]).at(-1)?.text||c.subtitle)}</span></span></button>`).join('')}</div><div class="conv-bottom">当前机组的群聊与单聊</div><div class="resize-x" data-resize="conversation" aria-hidden="true"></div></aside><article class="chat"><div class="chat-top"><div>${btn('back-conversations',icon('arrow'),'aria-label="返回会话列表"','icon-button mobile-back')}<h3 style="display:inline">${esc(conv.title)}</h3></div><div>${btn('simulate','完成这一步','title="体验计划项的完成与关联更新"')}${btn('inspector',icon('panel'),`aria-label="${state.inspector?'收起':'展开'} Todo 和成员" title="${state.inspector?'收起':'展开'} Todo 和成员"`,'icon-button')}</div></div><div class="chat-options"><div class="segmented">${btn('communication','人类沟通','data-mode="human"',state.mode==='human'?'active':'')}${btn('communication','完整记录','data-mode="all"',state.mode==='all'?'active':'')}</div>${btn('mentions','仅@你',`aria-pressed="${state.mentions}"`,state.mentions?'text-button on':'text-button')}<span class="quiet" style="font-size:10px">${filter==='all'?'全部消息':esc(filter)}</span></div><div class="messages" id="messages"><div class="time-separator">今天 13:20</div>${msgs.map((m,i)=>({...m,id:m.id||conv.id+'-'+i})).filter(m=>(filter==='all'||folderOf(m,'message')===filter)&&(!state.query||m.text.includes(state.query))&&(!state.mentions||m.sender==='你'||m.ref?.startsWith('H')||m.text.includes('@你'))&&(state.mode==='all'||!m.internal)).map(m=>message(m)).join('')||`<div class="empty">这个范围还没有消息。<br>${btn('clear-filters','看全部')}</div>`}</div><form class="composer" id="composer"><div class="composer-tools">${btn('new-request',icon('plus'),'title="新建原始需求" aria-label="新建原始需求"')}${btn('attachment',icon('file'),'title="添加体验文档引用" aria-label="添加体验文档引用"')}${btn('mention','@','title="插入成员提及"')}${btn('new-request','Todo')}${btn('reference-picker','引用')}</div><textarea id="draft" aria-label="输入消息" placeholder="输入消息…">${esc(state.drafts[conv.id]||'')}</textarea><div class="composer-bottom"><span>Enter 发送 · Shift + Enter 换行</span><button type="submit" class="primary">发送</button></div></form></article>${inspector()}`;}
function message(m){return `<div class="message ${m.sender==='你'?'own':''}">${m.sender==='你'?'':avatar(m.sender,false,m.sender===scene().agent?scene().glyph:'🦉')}<div class="message-body"><div class="sender">${esc(m.sender)}</div><div class="bubble">${esc(m.text)}${m.ref?ref(m.ref,'ref-link'):''}</div>${btn('move',icon('more'),`data-id="${esc(m.id)}" data-scope="message" aria-label="整理这条消息"`,'text-button message-menu')}</div></div>`;}
function inspector(){return `<aside class="inspector ${state.inspector?'force-visible':'hidden'}"><div class="panel todo-panel ${state.todoClosed?'closed':''}"><div class="panel-head">${btn('fold-todo',`<span class="chevron">${state.todoClosed?'▸':'▾'}</span> 本群 Todo`)}<span>${btn('todo-all','详细')}${btn('inspector','×','aria-label="收起辅助面板"','text-button inspector-close')}</span></div><div class="panel-content"><div class="quiet">同一账本的相关事项</div>${db().asks.filter(a=>['open','later'].includes(a.status)).map(a=>btn('reference',`<span class="state-ring blocked"></span><span>${esc(a.id)} ${esc(a.question)}<div class="sub">待人类处理 · ${a.status==='later'?'已稍后':'等你答复'}</div></span>`,`data-id="${a.id}"`,'mini-todo')).join('')}${db().plans.filter(p=>!p.parent||p.parent===db().plans[0].id).slice(0,3).map(p=>btn('reference',`<span class="state-ring ${p.status}"></span><span>${esc(p.code)} ${esc(p.title)}<div class="sub">${labels[p.status]} · ${esc(p.owner)}</div></span>`,`data-id="${p.id}"`,'mini-todo')).join('')}</div></div><div class="resize-y" data-resize="todo-height" aria-hidden="true"></div><div class="panel member-panel ${state.membersClosed?'closed':''}"><div class="panel-head">${btn('fold-members',`<span class="chevron">${state.membersClosed?'▸':'▾'}</span> 本群成员  3`)}</div><div class="panel-content">${[['你','人类','👤'],['机长','Codex · 跟进这件事','🦉'],[scene().agent,'Codex · 整理方案',scene().glyph]].map(([n,s,g])=>btn('member',`${avatar(n,false,g)}<span><span class="name">${esc(n)}</span><span class="sub" style="display:block">${esc(s)}</span></span>`,`data-name="${esc(n)}"`,'member-row')).join('')}</div></div></aside>`;}
function folderRail(){const scope=state.tab;return `<aside class="folder-rail"><div class="folder-head">文件夹 ${btn('new-folder',icon('plus'),'aria-label="新建文件夹"','icon-button')}</div>${['all',...db().folders[scope],'未分组'].map(f=>btn('select-folder',`${icon('folder')} ${f==='all'?'全部'+scopeNames[scope]:esc(f)}`,`data-folder="${esc(f)}"`,state.selectedFolders[scope]===f?'folder-button selected':'folder-button')).join('')}<div class="folder-bottom">${btn('folder-manager','管理分组')}</div></aside>`;}
function workspace(){const title=state.selectedFolders[state.tab]==='all'?{todo:'Todo',document:'机组文档',progress:'机组进展'}[state.tab]:state.selectedFolders[state.tab];return `${folderRail()}<article class="workspace"><header class="workspace-head"><div><h3>${esc(title)}</h3><p>${state.tab==='progress'?'同一份计划的进展视图 · 三层可折叠':state.tab==='todo'?'一本账 · 原始需求、计划、待人类处理':'说明、笔记与工作产物'}</p></div><div>${state.tab==='todo'?btn('new-request','＋ 原始需求'):state.tab==='progress'?btn('history','更新记录'):btn('new-doc','＋ 文档')}</div></header><div class="workspace-body">${state.tab==='todo'?todos():state.tab==='progress'?planTable(true):documents()}</div></article>`;}
function allAsks(){return DEMO_SCENARIOS.flatMap(s=>{const data=s.id===sceneId?state:cache[s.id]||(cache[s.id]=fresh(s.id));return data.db.asks.filter(a=>['open','later'].includes(a.status)).map(a=>({ask:a,scene:s}));});}
function todos(){return `<div class="segmented todo-kind">${[['requests','原始需求'],['plans','计划'],['asks','待人类处理']].map(([k,v])=>btn('todo-kind',v,`data-kind="${k}"`,state.kind===k?'active':'')).join('')}</div>${state.kind==='plans'?planTable(false):state.kind==='asks'?`<div class="segmented todo-kind">${btn('ask-scope','当前机组','data-scope="crew"',state.askScope!=='all'?'active':'')}${btn('ask-scope','全部机组 · 唯一收件箱','data-scope="all"',state.askScope==='all'?'active':'')}</div>${state.askScope==='all'?(allAsks().map(({ask,scene:s})=>`<p class="quiet" style="font-size:11px;margin:12px 0 7px">来源：${esc(s.crew)}</p>`+askCard(ask,s.id)).join('')||'<div class="empty">全部机组都没有等待人类的事项。</div>'):(filtered(db().asks,'todo').map(a=>askCard(a)).join('')||'<div class="empty">这里没有待人类处理的事项。</div>')}`:filtered(db().requests,'todo').map(r=>{const plans=db().plans.filter(p=>p.sources?.includes(r.id)),roots=plans.filter(p=>!p.parent);return `<section class="request-card"><div class="request-top"><strong>${esc(r.code)} 原始需求</strong>${statusBadge(roots.length?roots.every(p=>p.status==='done')?'done':'active':'open')}</div><p class="original-text">${esc(r.text)}</p>${roots.map(p=>ref(p.id)).join('')}<details open><summary>关联计划 · 展开三层</summary>${planTable(false,r.id)}</details><div style="margin-top:10px">${btn('move','移动到文件夹',`data-id="${r.id}" data-scope="todo"`)}</div></section>`;}).join('')||'<div class="empty">这里没有原始需求。</div>'}`;}
function planTable(progress=false,source=null){let plans=db().plans.filter(p=>!source||p.sources?.includes(source));if(!source)plans=filtered(plans,progress?'progress':'todo');const ids=new Set(plans.map(p=>p.id));function row(p,depth){const children=plans.filter(c=>c.parent===p.id);return `<tr data-plan="${p.id}"><td><div class="plan-title" data-depth="${depth}">${children.length?btn('fold-plan',state.collapsed.includes(p.id)?'▸':'▾',`data-id="${p.id}" aria-label="${state.collapsed.includes(p.id)?'展开':'折叠'} ${p.code}"`):'<span class="chevron"></span>'}${btn('reference',`${esc(p.title)}<span class="plan-code">${esc(p.code)} · ${p.id}</span>`,`data-id="${p.id}"`,'plan-open')}</div></td><td>${statusBadge(p.status)}</td><td>${esc(p.owner||'待认领')}</td>${progress?`<td class="plan-note">${esc(p.note||'—')}</td><td>${p.blockedOn.length?p.blockedOn.map(id=>ref(id)).join(''):esc(p.nextCheck||'—')}</td>`:`<td>${p.dependsOn.map(id=>ref(id)).join('')||'—'}</td>`}</tr>${state.collapsed.includes(p.id)?'':children.map(c=>row(c,depth+1)).join('')}`;}const html=plans.filter(p=>!p.parent||!ids.has(p.parent)).map(p=>row(p,0)).join('');return html?`<div class="table-wrap"><table class="plan-table"><thead><tr><th>计划 · 最多三层</th><th>状态</th><th>负责人</th>${progress?'<th>下一步／备注</th><th>卡点／下一检查</th>':'<th>依赖</th>'}</tr></thead><tbody>${html}</tbody></table></div><p class="table-caption">${progress?'点击标题查看目标、完成层级、验收标准和产物；这里与 Todo 的计划共用一份数据。':'层级表示拆解，依赖单独显示。文件夹只负责分类。'}</p>`:'<div class="empty">这个文件夹还没有计划。</div>';}
function askCard(a,origin=sceneId){return `<section class="ask-card"><span class="badge blocked">${esc(a.id)} · ${a.status==='open'?'等待你的答复':a.status==='later'?'稍后处理':a.status==='answered'?'已答复':'已撤回'}</span><h4>${esc(a.question)}</h4><p>${esc(a.context)}</p>${ref(a.item)}${['open','later'].includes(a.status)?`<p style="margin-top:12px">推荐：${esc(a.recommendation)}</p><div class="ask-actions">${a.options.map((o,i)=>btn('answer',esc(o),`data-id="${a.id}" data-scene="${origin}" data-choice="${i}"`,i===0?'recommended':'')).join('')}${btn('ask-later','稍后',`data-id="${a.id}" data-scene="${origin}"`)}${btn('ask-withdraw','不要了',`data-id="${a.id}" data-scene="${origin}"`)}</div>`:`<p style="margin-top:12px">${esc(a.answer||'已经撤回，不再等待答复。')}</p>`}</section>`;}
function documents(){const d=db().docs.find(d=>d.id===state.doc);return d?`<div class="doc-reader">${btn('back-documents','← 返回文档')}<h3>${esc(d.title)}</h3><div class="byline">${esc(d.author)} · 体验文档</div>${d.body.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}${sceneId==='research'?'<p><a href="https://docs.pendingname.com/pendingcrew" target="_blank" rel="noopener">完整使用文档 ↗</a>　<a href="https://github.com/syncmeta/PendingCrew/releases" target="_blank" rel="noopener">下载 PendingCrew ↗</a></p>':''}${ref(db().plans[0].id)}${btn('move','移动到文件夹',`data-id="${d.id}" data-scope="document"`)}</div>`:filtered(db().docs,'document').map(d=>btn('reference',`<span class="doc-symbol">${icon('file')}</span><span>${esc(d.title)}<small>${esc(d.author)} · ${esc(folderOf(d,'document'))}</small></span>`,`data-id="${d.id}"`,'doc-row')).join('')||'<div class="empty">这里还没有文档。</div>';}
function render(){const oldScroll=document.querySelector('#messages')?.scrollTop;app.innerHTML=shell();if(oldScroll!=null&&state.tab==='message')document.querySelector('#messages').scrollTop=oldScroll;}
function openModal(title,body,actions=''){modal.innerHTML=`<div class="dialog-head"><h3>${esc(title)}</h3>${btn('close',icon('plus'),'aria-label="关闭详情" style="transform:rotate(45deg)"','icon-button')}</div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!dialog.open)dialog.showModal();}
function openReference(id){const p=db().plans.find(p=>p.id===id),a=db().asks.find(a=>a.id===id),d=db().docs.find(d=>d.id===id),r=db().requests.find(r=>r.id===id);if(p){openModal(p.code+' · '+p.title,`<div class="quiet" style="font-size:11px">稳定编号 ${p.id} · 与 Todo／进展引用同一份记录</div><div class="dialog-fields" style="margin-top:16px"><label>状态<select id="plan-status">${['open','active','done'].map(s=>`<option value="${s}" ${p.status===s?'selected':''}>${labels[s]}</option>`).join('')}${p.status==='blocked'?'<option value="blocked" selected>等待答复</option>':''}</select></label><label>负责人<select id="plan-owner">${['机长',scene().agent].map(o=>`<option ${p.owner===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label></div><h4>目标</h4><p>${esc(p.goal||db().plans[0].goal)}</p><h4>完成层级与验收标准</h4><p>本地方案 · ${esc(p.acceptance||db().plans[0].acceptance)}</p><h4>下一步／备注（覆盖更新）</h4><textarea id="plan-note" aria-label="计划备注">${esc(p.note)}</textarea><h4>来源、依赖与卡点</h4><p>${(p.sources||[]).map(id=>ref(id)).join('')} ${p.dependsOn.map(id=>ref(id)).join('')} ${p.blockedOn.map(id=>ref(id)).join('')||'没有等待人类的卡点'}</p>${p.evidence?`<h4>产物</h4>${ref(p.evidence)}`:''}<h4>下一检查</h4><p>${esc(p.nextCheck)}</p>`,btn('move','移动到文件夹',`data-id="${p.id}" data-scope="${state.tab==='todo'?'todo':'progress'}"`)+btn('save-plan','保存修改',`data-id="${p.id}"`,'primary'));}else if(a){openModal('待人类处理 · '+a.id,askCard(a));}else if(d){dialog.close();state.tab='document';state.doc=d.id;state.selectedFolders.document='all';render();persist();}else if(r){dialog.close();state.tab='todo';state.kind='requests';state.selectedFolders.todo='all';render();persist();}else {const source=DEMO_SCENARIOS.find(s=>s.id!==sceneId&&[...(cache[s.id]||(cache[s.id]=fresh(s.id))).db.plans,...cache[s.id].db.asks,...cache[s.id].db.docs,...cache[s.id].db.requests].some(x=>x.id===id));if(source){selectScene(source.id);openReference(id);}else toast('这个引用已经不可用。');}}
function manageFolders(){const scope=state.tab;openModal('管理'+scopeNames[scope]+'文件夹',`<p class="quiet">这个视图的分类独立于机组层级和其他视图。已有内容移动后仍保留原编号与引用。</p><div class="dialog-list">${db().folders[scope].map(f=>`<button data-action="rename-folder" data-folder="${esc(f)}">${icon('folder')} ${esc(f)} <small>点击重命名</small></button>`).join('')}</div>`,btn('new-folder','＋ 新建文件夹','','primary'));}
function editFolder(old=null){openModal(old?'重命名文件夹':'新建文件夹',`<label>文件夹名称<input id="folder-name" aria-label="文件夹名称" style="width:100%;margin-top:9px" value="${esc(old||'')}" placeholder="例如：本周讨论"></label>`,btn('save-folder','保存',old?`data-old="${esc(old)}"`:'','primary'));}
function move(id,scope){openModal('移动到'+scopeNames[scope]+'文件夹',`<p class="quiet">只改变分类，原始记录与引用不变。</p><div class="dialog-list">${[...db().folders[scope],'未分组'].map(f=>btn('confirm-move',`${icon('folder')} ${esc(f)}`,`data-id="${esc(id)}" data-scope="${scope}" data-folder="${esc(f)}"`,'')).join('')}</div>`);}
function answer(id,text){const a=db().asks.find(a=>a.id===id);if(!a||!['open','later'].includes(a.status))return;a.status='answered';a.answer=text;for(const p of db().plans.filter(p=>p.blockedOn.includes(id))){p.blockedOn=p.blockedOn.filter(x=>x!==id);if(!p.blockedOn.length){p.status='active';p.nextCheck='现在跟进';p.note='已收到你的答复：'+text;}}addMessage('你',text,id);addMessage('机长','收到。'+a.item+' 的等待已解除，其他计划和进展也已同步。',a.item);record('你回答了 '+id+'；关联计划恢复推进。');dialog.close();render();persist();toast('答复已保存；同一事项的所有引用已更新。');}
function record(text){db().history.push({text,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})});}
function addMessage(sender,text,refId=null,convId=sceneId+'-main',internal=false){state.counter++;const m={id:'message-'+sceneId+'-'+state.counter,sender,text,ref:refId,internal,folder:db().folders.message[0]};db().messages[convId].push(m);return m;}
function scrollBottom(){requestAnimationFrame(()=>{const el=document.querySelector('#messages');if(el)el.scrollTop=el.scrollHeight;});}
function send(){const text=document.querySelector('#draft').value.trim();if(!text)return;addMessage('你',text,null,state.conv);state.drafts[state.conv]='';render();persist();scrollBottom();toast('消息已加入演示；这里不会调用真实模型。');}
function showSearch(){openModal('搜索当前体验',`<input id="modal-search" aria-label="搜索所有体验内容" placeholder="输入计划、文档或问题中的文字" style="width:100%"><div id="search-results" style="margin-top:15px"></div>`);document.querySelector('#modal-search').focus();}
function searchResults(q){const items=[...db().plans.map(p=>({id:p.id,title:p.title,kind:'计划'})),...db().asks.map(a=>({id:a.id,title:a.question,kind:'待人类处理'})),...db().docs.map(d=>({id:d.id,title:d.title,kind:'文档'})),...db().requests.map(r=>({id:r.id,title:r.text,kind:'原始需求'}))];return items.filter(x=>x.title.includes(q)).map(x=>btn('reference',`${esc(x.title)}<small>${x.kind} · ${x.id}</small>`,`data-id="${x.id}"`,'search-result')).join('')||'<div class="empty">没有找到相关内容。</div>';}
function guide(){openModal('从 PendingCrew 自己的介绍开始',`<p class="quiet">${esc(scene().brief)}</p>${[['交代需求','在本群发消息，或点输入区的 Todo，把原文保存为原始需求。'],['展开三层计划','打开 Todo → 计划，点击箭头展开 P1、P1-2、P1-2-1。点击标题查看负责人和验收标准。'],['在需要你时答复','打开待人类处理，选一个推荐方案。只解除关联计划的等待，其他工作继续。'],['查看进展和文档','进展引用同一份计划。改一次备注，Todo 里也会更新；点产物查看文档。']].map(([t,p],i)=>`<div class="guide-step"><span class="guide-number">${i+1}</span><div><h4>${t}</h4><p>${p}</p></div></div>`).join('')}<p class="quiet" style="margin-top:16px">消息、Todo、文档、进展各有自己的文件夹。操作保存在这个浏览器里，可以随时重置。</p>`,btn('start-guide','先看看三层计划','','primary'));}
function handleAction(el){const a=el.dataset.action,id=el.dataset.id;if(el.dataset.scene&&el.dataset.scene!==sceneId){selectScene(el.dataset.scene);state.tab='todo';state.kind='asks';}
switch(a){
case 'scene':dialog.close();selectScene(id);return;
case 'sidebar':state.sidebar=el.dataset.mode;break;
case 'machine':state.machineClosed=!state.machineClosed;break;
case 'tab':state.tab=el.dataset.tab;state.query='';state.doc=null;break;
case 'conversation':state.conv=id;state.mobileChat=true;state.query='';break;
case 'back-conversations':state.mobileChat=false;break;
case 'mobile-menu':app.classList.toggle('show-sidebar');return;
case 'close-sidebar':app.classList.remove('show-sidebar');return;
case 'inspector':state.inspector=!state.inspector;break;
case 'fold-todo':state.todoClosed=!state.todoClosed;break;
case 'fold-members':state.membersClosed=!state.membersClosed;break;
case 'todo-all':state.tab='todo';state.kind='asks';state.selectedFolders.todo='all';break;
case 'member':if(el.dataset.name==='你'){toast('你是这个体验中的人类成员。');return;}state.conv=el.dataset.name===scene().agent?sceneId+'-agent':sceneId+'-captain';if(!db().conversations.some(c=>c.id===state.conv)){db().conversations.push({id:state.conv,title:'机长',kind:'dm',subtitle:'关于这件事的沟通'});db().messages[state.conv]=[{sender:'机长',text:'你可以在这里单独讨论计划。群内的计划与文档仍是同一份。',ref:db().plans[0].id}];}state.mobileChat=true;break;
case 'todo-kind':state.kind=el.dataset.kind;break;
case 'ask-scope':state.askScope=el.dataset.scope;break;
case 'select-folder':state.selectedFolders[state.tab]=el.dataset.folder;state.doc=null;break;
case 'fold-plan':state.collapsed=state.collapsed.includes(id)?state.collapsed.filter(x=>x!==id):[...state.collapsed,id];break;
case 'reference':openReference(id);return;
case 'close':dialog.close();return;
case 'guide':guide();return;
case 'start-guide':dialog.close();state.tab='todo';state.kind='plans';state.collapsed=[];break;
case 'folder-manager':manageFolders();return;
case 'new-folder':editFolder();return;
case 'rename-folder':editFolder(el.dataset.folder);return;
case 'save-folder':{const scope=state.tab,name=document.querySelector('#folder-name').value.trim(),old=el.dataset.old;if(!name){toast('请输入文件夹名称。');return;}if(name==='all'||name==='未分组'||db().folders[scope].includes(name)&&name!==old){toast('这个名称已存在，请换一个名称。');return;}if(old){db().folders[scope]=db().folders[scope].map(f=>f===old?name:f);for(const collection of [db().plans,db().requests,db().asks,db().docs,...Object.values(db().messages)])for(const item of collection)if(folderOf(item,scope)===old)db().placements[scope+':'+item.id]=name;if(state.selectedFolders[scope]===old)state.selectedFolders[scope]=name;}else db().folders[scope].push(name);dialog.close();toast('文件夹已保存。');break;}
case 'move':move(id,el.dataset.scope);return;
case 'confirm-move':db().placements[el.dataset.scope+':'+id]=el.dataset.folder;dialog.close();toast('已移动，原编号和引用保持不变。');break;
case 'answer':answer(id,db().asks.find(a=>a.id===id).options[Number(el.dataset.choice)]);return;
case 'ask-later':db().asks.find(a=>a.id===id).status='later';dialog.close();toast('已稍后处理，相关计划继续等待。');break;
case 'ask-withdraw':{const ask=db().asks.find(a=>a.id===id);ask.status='withdrawn';ask.answer='你选择不要了，相关待确认部分结束。';for(const p of db().plans.filter(p=>p.blockedOn.includes(id))){p.status='dropped';p.blockedOn=[];p.note='因人类撤回事项，这一部分不再继续。';}dialog.close();record('你撤回了 '+id+'；关联部分结束。');break;}
case 'save-plan':{const p=db().plans.find(p=>p.id===id),status=document.querySelector('#plan-status').value;if(p.blockedOn.some(h=>['open','later'].includes(db().asks.find(a=>a.id===h)?.status))&&status!=='blocked'){toast('这项仍在等你的答复，请先处理关联问题。');return;}if(status==='done'&&db().plans.some(c=>c.parent===id&&!['done','dropped'].includes(c.status))){toast('先结束子计划，再完成这一层。');return;}if(status==='active'&&p.dependsOn.some(dep=>db().plans.find(x=>x.id===dep)?.status!=='done')){toast('依赖计划还没有完成。');return;}p.status=status;p.note=document.querySelector('#plan-note').value;p.owner=document.querySelector('#plan-owner').value;p.nextCheck=status==='done'?'—':'今天 15:00';if(status==='done')p.evidence=db().docs.find(d=>d.title===scene().docTitle).id;record(p.code+' 更新为'+labels[status]+'，备注已保存。');dialog.close();toast('已更新：Todo 和进展使用同一份计划。');break;}
case 'back-documents':state.doc=null;break;
case 'communication':state.mode=el.dataset.mode;break;
case 'mentions':state.mentions=!state.mentions;break;
case 'clear-filters':state.mentions=false;state.query='';state.selectedFolders.message='all';break;
case 'search':showSearch();return;
case 'refresh':render();toast('体验状态已刷新。');return;
case 'hidden':toast('这份介绍里没有隐藏的机组。');return;
case 'history':openModal('计划更新记录',db().history.slice().reverse().map(h=>`<div class="timeline-entry"><time>${esc(h.time)}</time><span>${esc(h.text)}</span></div>`).join(''));return;
case 'new-crew':openModal('新建体验机组',`<label>机组名称<input id="crew-name" aria-label="机组名称" style="width:100%;margin-top:8px" placeholder="例如：读书计划"></label><h4>要交给这个团队的事</h4><textarea id="crew-brief" aria-label="机组任务" placeholder="写下一个想一起完成的目标"></textarea>`,btn('save-crew','创建体验机组','','primary'));return;
case 'save-crew':{const name=document.querySelector('#crew-name').value.trim(),brief=document.querySelector('#crew-brief').value.trim();if(!name||!brief){toast('请填入名称和目标。');return;}const base=structuredClone(DEMO_SCENARIOS[2]);base.id='custom-'+Date.now();base.name=name;base.crew=name;base.project=name;base.request=brief;base.brief=brief;base.question='这个体验里，下一步优先完善方案还是继续收集资料？';base.recommendation='先完善方案';base.options=['先完善方案','继续收集资料'];base.steps=['整理原始需求','形成可讨论的方案','准备交付说明'];base.leaf='核对方案中的关键问题';base.docTitle=name+'说明.md';base.docBody=brief+'\n\n这是你在浏览器里创建的体验机组，三层计划是演示用的拆解，没有真实调用模型。';base.note='已保留需求，正在整理演示方案。';DEMO_SCENARIOS.push(base);document.querySelector('#scenario').innerHTML=DEMO_SCENARIOS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');dialog.close();selectScene(base.id);toast('体验机组已创建，只保存在这个浏览器里。');return;}
case 'new-request':openModal('新建原始需求',`<p class="quiet">保留你交代的原文，计划通过引用关联到这里。</p><textarea id="request-text" aria-label="原始需求内容" placeholder="你想让团队做什么？"></textarea>`,btn('save-request','保存原始需求','','primary'));return;
case 'save-request':{const text=document.querySelector('#request-text').value.trim();if(!text){toast('先写下你的需求。');return;}const number=Math.max(...db().requests.map(r=>Number(r.id.slice(1))))+1;db().requests.unshift({id:'N'+number,code:'#'+number,text,folder:db().folders.todo[0]});addMessage('你',text,'N'+number);dialog.close();state.tab='todo';state.kind='requests';state.selectedFolders.todo='all';toast('原文已保存，尚未生成计划。');break;}
case 'new-doc':openModal('新建体验文档',`<input id="doc-title" aria-label="文档名称" placeholder="文档名称" style="width:100%"><textarea id="doc-body" aria-label="文档正文" placeholder="写下说明或笔记" style="margin-top:12px"></textarea>`,btn('save-doc','保存文档','','primary'));return;
case 'save-doc':{const title=document.querySelector('#doc-title').value.trim();if(!title){toast('请输入文档名称。');return;}const d={id:'D'+(Math.max(...db().docs.map(d=>Number(d.id.slice(1))))+1),title,body:document.querySelector('#doc-body').value,author:'你',folder:db().folders.document[0]};db().docs.unshift(d);state.doc=d.id;dialog.close();break;}
case 'attachment':case 'reference-picker':openModal('插入体验引用',`<div class="dialog-list">${[...db().docs,...db().plans].map(x=>btn('insert-reference',esc(refLabel(x.id)),`data-id="${x.id}"`,'')).join('')}</div>`);return;
case 'insert-reference':addMessage('你','分享一条关联记录：',id,state.conv);dialog.close();render();persist();scrollBottom();return;
case 'mention':{const t=document.querySelector('#draft');t.value+='@'+scene().agent+' ';state.drafts[state.conv]=t.value;t.focus();persist();return;}
case 'simulate':{const p=db().plans.find(p=>p.parent&&db().plans.some(q=>q.id===p.parent&&q.parent));if(p.status==='done'){toast('这一步已演示完成，可以换个体验或重置。');return;}p.status='done';p.note='这一步已读完，说明保存在关联文档里。';p.evidence=db().docs.find(d=>d.title===scene().docTitle).id;db().docs.find(d=>d.title===scene().docTitle).body+='\n\n阅读记录：'+p.title+'已经完成。';record(scene().agent+'完成 '+p.code+' 并更新文档。');addMessage(scene().agent,'刚完成 '+p.code+'，成果已补进文档。',p.id);addMessage('系统','完整记录：体验检查点已处理。',p.id,state.conv,true);toast('阅读进度已更新，计划与进展保持一致。');render();persist();scrollBottom();return;}
default:return;}
render();persist();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)handleAction(el);});
document.addEventListener('submit',e=>{if(e.target.id==='composer'){e.preventDefault();send();}});
document.addEventListener('input',e=>{if(e.target.id==='draft'){state.drafts[state.conv]=e.target.value;persist();}else if(e.target.id==='modal-search')document.querySelector('#search-results').innerHTML=searchResults(e.target.value);else if(e.target.id==='search-input'){const start=e.target.selectionStart;state.query=e.target.value;render();persist();const field=document.querySelector('#search-input');field.focus();field.setSelectionRange(start,start);}});
document.addEventListener('change',e=>{if(e.target.dataset.folderScope){state.selectedFolders[e.target.dataset.folderScope]=e.target.value;render();persist();}});
document.addEventListener('keydown',e=>{if(e.target.id==='draft'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send();}});
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-resize]');if(!handle)return;e.preventDefault();const name=handle.dataset.resize,startX=e.clientX,startY=e.clientY,style=getComputedStyle(document.documentElement),initial=parseFloat(style.getPropertyValue('--'+name)),inspector=document.querySelector('.inspector'),height=inspector?.getBoundingClientRect().height||600;handle.setPointerCapture(e.pointerId);function move(ev){let value=name==='todo-height'?Math.max(15,Math.min(75,initial+(ev.clientY-startY)/height*100)):Math.max(name==='sidebar'?190:165,Math.min(name==='sidebar'?330:300,initial+ev.clientX-startX));document.documentElement.style.setProperty('--'+name,value+(name==='todo-height'?'%':'px'));}function end(){handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);}handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);});
dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
document.querySelector('#scenario').innerHTML=DEMO_SCENARIOS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');document.querySelector('#scenario').onchange=e=>{dialog.close();selectScene(e.target.value);};document.querySelector('#guide').onclick=guide;
document.querySelector('#reset').onclick=()=>openModal('重置阅读体验',`<p>清除你在「${esc(scene().name)}」里的消息、答复和修改，回到最初的体验状态。其他体验不受影响。</p>`,btn('close','取消')+`<button class="primary" id="confirm-reset">重置这个体验</button>`);
document.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){delete cache[sceneId];state=fresh(sceneId);dialog.close();render();persist();toast('已恢复最初的体验。');}});
if(new URLSearchParams(location.search).get('embed')==='1')document.body.classList.add('embed');selectScene(sceneId);
})();
